add_shortcode( 'geo_content', 'perfectpixel_geo_content_shortcode' );

function perfectpixel_visitor_country() {
	static $country = null;
	if ( null === $country ) {
		$location = class_exists( 'WC_Geolocation' ) ? WC_Geolocation::geolocate_ip( '', true, true ) : array();
		$country  = ! empty( $location['country'] ) ? $location['country'] : '';
	}
	return $country;
}

function perfectpixel_geo_content_shortcode( $atts, $content = '' ) {
	$atts      = shortcode_atts( array( 'countries' => '', 'exclude' => 'no' ), $atts );
	$countries = array_filter( array_map( 'trim', explode( ',', strtoupper( $atts['countries'] ) ) ) );
	if ( ! $countries ) {
		return '';
	}
	$match = in_array( perfectpixel_visitor_country(), $countries, true );
	$show  = 'yes' === $atts['exclude'] ? ! $match : $match;
	return $show ? do_shortcode( $content ) : '';
}
